#include "support/session_image_peer.h"
static void testImageRoundtrip(xmqttversion V,bool Live)
{
    xmqttsession* S=miPopulate(V,Live);xmqttsessionconfig K=miSessionConfig(V);xmqttsessionimageconfig C=miConfig(11,1000000);unsigned char Image[4096];size_t N=miWrite(S,&C,Image,sizeof(Image));
    testRequire(!memcmp(Image,"XMQSIMG\0",8)&&Image[8]==0&&Image[9]==1&&Image[12]==V,"literal private format/version");xmqttsession* R=NULL;C=miConfig(5,1001500);miStatus(xmqttSessionImageRestore(&K,&C,(xbytesview){Image,N},&R),XMQTT_SESSION_DONE,"full image restore");memset(Image,0xcc,N);miStop(S,12);miReplay(R,V,5);miStop(R,6);
}
static void testImageExpiry(void)
{
    xmqttsession* S=miPopulate(XMQTT_VERSION_5,false);xmqttsessionconfig K=miSessionConfig(XMQTT_VERSION_5);xmqttsessionimageconfig C=miConfig(11,1000000);unsigned char Image[4096];size_t N=miWrite(S,&C,Image,sizeof(Image));miStop(S,12);C=miConfig(5,1001500);xmqttsession* R=NULL;miStatus(xmqttSessionImageRestore(&K,&C,(xbytesview){Image,N},&R),XMQTT_SESSION_DONE,"finite expiry rebase");miStatus(xmqttSessionExpire(R,62.749),XMQTT_SESSION_EMPTY,"remaining57.750 seconds not extended/rounded to whole seconds");miStatus(xmqttSessionExpire(R,62.75),XMQTT_SESSION_DONE,"downtime consumed precise remaining lifetime");testRequire(!miInfo(R).HasState,"expired state cleared");miStop(R,63);
    C=miConfig(0,1060000);miStatus(xmqttSessionImageRestore(&K,&C,(xbytesview){Image,N},&R),XMQTT_SESSION_RESET,"already expired restore publishes empty");testRequire(!miInfo(R).HasState&&!miInfo(R).Objects,"expired restore refunds packet owners");miStop(R,0);
    C=miConfig(1e300,1001500);miStatus(xmqttSessionImageRestore(&K,&C,(xbytesview){Image,N},&R),XMQTT_SESSION_DONE,"new huge monotonic epoch");miStatus(xmqttSessionExpire(R,1e300),XMQTT_SESSION_EMPTY,"display deadline rounding cannot prematurely expire at huge clock");miStatus(xmqttSessionExpire(R,nextafter(1e300,INFINITY)),XMQTT_SESSION_DONE,"large positive elapsed time expires");miStop(R,nextafter(1e300,INFINITY));
    S=miPopulate(XMQTT_VERSION_5,true);C=miConfig(2,1000000);N=miWrite(S,&C,Image,sizeof(Image));miStop(S,3);C=miConfig(0,1000000000000ULL);miStatus(xmqttSessionImageRestore(&K,&C,(xbytesview){Image,N},&R),XMQTT_SESSION_DONE,"unknown live disconnect time is not guessed from old checkpoint");testRequire(miInfo(R).HasState&&isinf(miInfo(R).ExpiresAt),"live candidate held for actual broker decision");miStatus(xmqttSessionExpire(R,100000),XMQTT_SESSION_EMPTY,"live candidate does not fabricate an expired session");miStatus(miOpen(R,XMQTT_VERSION_5,false,false,60,100001),XMQTT_SESSION_RESET,"actual broker absence resets live candidate");testRequire(!miInfo(R).ActiveOutgoing&&!miInfo(R).Incoming,"fresh negotiation discards stale protocol obligations");miStop(R,100002);
}
static void testImageNonpersistent(xmqttversion V)
{
    xmqttsession* S=miCreate(V);miStatus(miOpen(S,V,true,false,0,1),XMQTT_SESSION_DONE,"nonpersistent live source");const xmqttsessionpacket* P=miPublish(S,1,1);unsigned char Image[1024];xmqttsessionimageconfig C=miConfig(2,100);size_t N=miWrite(S,&C,Image,sizeof(Image));xmqttsessionconfig K=miSessionConfig(V);xmqttsession* R=NULL;miStatus(xmqttSessionImageRestore(&K,&C,(xbytesview){Image,N},&R),XMQTT_SESSION_DONE,"nonpersistent snapshot is empty retained state");testRequire(!miInfo(R).HasState&&!miInfo(R).ActiveOutgoing,"no replay under nonpersistent mode");miStop(S,3);testRequire(xmqttSessionPacket(P)->Identifier==1,"old external immutable snapshot still valid");xmqttSessionPacketRelease(P);miStop(R,2);
}
static void testImagePropertiesAndPartial(void)
{
    xmqttsession* S=miCreate(XMQTT_VERSION_5);miStatus(miOpen(S,XMQTT_VERSION_5,false,false,UINT32_MAX,1),XMQTT_SESSION_DONE,"infinite source with MQTT5 properties");
    xmqttproperty Props[4]={{0}};Props[0].Id=XMQTT_PROPERTY_USER;Props[0].Type=XMQTT_PROPERTY_STRING_PAIR;Props[0].Value.Pair.Name=XRT_STR_LITERAL("name");Props[0].Value.Pair.Value=XRT_STR_LITERAL("value");Props[1].Id=XMQTT_PROPERTY_CORRELATION_DATA;Props[1].Type=XMQTT_PROPERTY_BINARY;Props[1].Value.Binary=XRT_BYTES_LITERAL("a\0b");Props[2].Id=XMQTT_PROPERTY_PAYLOAD_FORMAT;Props[2].Type=XMQTT_PROPERTY_BYTE;Props[2].Value.Number=1;Props[3].Id=XMQTT_PROPERTY_TOPIC_ALIAS;Props[3].Type=XMQTT_PROPERTY_UINT16;Props[3].Value.Number=1;
    xmqttpacket Q;xmqttPacketInit(XMQTT_PACKET_PUBLISH,&Q);Q.Flags=4;Q.Identifier=30;Q.Body.Publish.Topic=XRT_STR_LITERAL("image/topic");Q.Body.Publish.Payload=XRT_BYTES_LITERAL("x\0z");Q.Properties=(xmqttpropertylist){Props,4};const xmqttsessionpacket* Held=NULL;miStatus(xmqttSessionPublish(S,&Q,&Held),XMQTT_SESSION_DONE,"property-rich canonical source");testRequire(xmqttSessionPacket(Held)->Properties.Count==3,"connection alias excluded from retained wire");
    xmqttsessionframe Partial=miNext(S,XMQTT_PACKET_PUBLISH,30,false);unsigned char Image[4096];xmqttsessionimageconfig C=miConfig(2,100);size_t N=miWrite(S,&C,Image,sizeof(Image));xmqttsessionconfig K=miSessionConfig(XMQTT_VERSION_5);xmqttsession* R=NULL;C=miConfig(0,1000000);miStatus(xmqttSessionImageRestore(&K,&C,(xbytesview){Image,N},&R),XMQTT_SESSION_DONE,"selected/incomplete native output is conservatively attempted");miStop(S,3);testRequire(Partial.Tail.Size&&xmqttSessionPacket(Held)->Properties.Count==3,"original selected frame/property storage survives old Session");xmqttSessionPacketRelease(Partial.Packet);xmqttSessionPacketRelease(Held);memset(Image,0xcc,N);miStatus(miOpen(R,XMQTT_VERSION_5,false,true,60,0),XMQTT_SESSION_DONE,"restored independent property-ready generation");xmqttsessionframe F=miNext(R,XMQTT_PACKET_PUBLISH,30,true);const xmqttpacket* P=xmqttSessionPacket(F.Packet);testRequire(P->Properties.Count==3&&P->Properties.Data[0].Value.Pair.Value.Size==5&&!memcmp(P->Properties.Data[0].Value.Pair.Value.Data,"value",5)&&P->Properties.Data[1].Value.Binary.Size==3&&!memcmp(P->Properties.Data[1].Value.Binary.Data,"a\0b",3)&&P->Properties.Data[2].Value.Number==1,"copied property descriptors/binary data remain correct after image/source erasure");miSent(R,F);miAck(R,XMQTT_PACKET_PUBREC,30,0);F=miNext(R,XMQTT_PACKET_PUBREL,30,false);miSent(R,F);miAck(R,XMQTT_PACKET_PUBCOMP,30,0);miStop(R,1);
}
static void testImageAssigned(void)
{
    xmqttsessionconfig K=miSessionConfig(XMQTT_VERSION_5);K.ClientId=(xstrview){0};xmqttsession* S=NULL;testRequire(xmqttSessionCreateUnassigned(&K,64,&S),"unassigned image source");xmqttsessionimageconfig C=miConfig(0,100);size_t Count=123;miStatus(xmqttSessionImageSize(S,&C,&Count),XMQTT_SESSION_STATE_ERROR,"unbound identity cannot enter protocol image");testRequire(Count==123,"unbound image output unchanged");xrtClearError();
    xmqttpacket Connect,Ack;xmqttPacketInit(XMQTT_PACKET_CONNECT,&Connect);xmqttPacketInit(XMQTT_PACKET_CONNACK,&Ack);xmqttproperty Expiry={0},Id={0};Expiry.Id=XMQTT_PROPERTY_SESSION_EXPIRY;Expiry.Type=XMQTT_PROPERTY_UINT32;Expiry.Value.Number=60;Connect.Properties=(xmqttpropertylist){&Expiry,1};Id.Id=XMQTT_PROPERTY_ASSIGNED_CLIENT_ID;Id.Type=XMQTT_PROPERTY_STRING;Id.Value.Text=XRT_STR_LITERAL("server-assigned-42");Ack.Properties=(xmqttpropertylist){&Id,1};xmqttnegotiated Negotiated;miStatus(xmqttSessionOpen(S,&Connect,&Ack,1,&Negotiated),XMQTT_SESSION_DONE,"server assigned identity accepted once");const xmqttsessionpacket* P=miPublish(S,1,51);xmqttSessionPacketRelease(P);miSent(S,miNext(S,XMQTT_PACKET_PUBLISH,51,false));miStatus(xmqttSessionEnd(S,NULL,2),XMQTT_SESSION_DONE,"assigned connection ended");C=miConfig(3,1000);unsigned char Image[4096];size_t N=miWrite(S,&C,Image,sizeof(Image));miStop(S,4);C=miConfig(0,1100);xmqttsession* R=(xmqttsession*)(uintptr_t)1;
    miStatus(xmqttSessionImageRestore(&K,&C,(xbytesview){Image,N},&R),XMQTT_SESSION_ERROR,"normal restore never silently adopts identity");testRequire(R==(xmqttsession*)(uintptr_t)1,"normal missing identity output unchanged");xrtClearError();miStatus(xmqttSessionImageRestoreAssigned(&K,&C,(xbytesview){Image,N},&R),XMQTT_SESSION_DONE,"explicit assigned-id restore");memset(Image,0xcc,N);xstrview Bound;testRequire(xmqttSessionClientId(R,&Bound)&&Bound.Size==18&&!memcmp(Bound.Data,"server-assigned-42",18),"restored assigned identity owns stable bytes");Connect.Body.Connect.ClientId=Bound;Ack.Properties=(xmqttpropertylist){0};Ack.SessionPresent=true;miStatus(xmqttSessionOpen(R,&Connect,&Ack,0,&Negotiated),XMQTT_SESSION_DONE,"fresh CONNECT uses recovered exact identity");xmqttsessionframe F=miNext(R,XMQTT_PACKET_PUBLISH,51,true);miSent(R,F);miAck(R,XMQTT_PACKET_PUBACK,51,0);miStop(R,1);
}
static int imageFile(int Argc,char** Argv)
{
    testRequire(Argc==4&&(!strcmp(Argv[1],"--write")||!strcmp(Argv[1],"--read")),"file interchange arguments");xmqttversion V=!strcmp(Argv[3],"5")?XMQTT_VERSION_5:XMQTT_VERSION_311;unsigned char B[4096];size_t N;FILE* F;
    if(!strcmp(Argv[1],"--write")){xmqttsession* S=miPopulate(V,false);xmqttsessionimageconfig C=miConfig(11,1000000);N=miWrite(S,&C,B,sizeof(B));F=fopen(Argv[2],"wb");testRequire(F&&fwrite(B,1,N,F)==N&&fclose(F)==0,"write actual portable image");miStop(S,12);}
    else{F=fopen(Argv[2],"rb");testRequire(F!=NULL,"read actual other-platform image");N=fread(B,1,sizeof(B),F);testRequire(!ferror(F)&&feof(F)&&fclose(F)==0,"bounded complete image read");xmqttsessionconfig K=miSessionConfig(V);xmqttsessionimageconfig C=miConfig(5,1001500);xmqttsession* R=NULL;miStatus(xmqttSessionImageRestore(&K,&C,(xbytesview){B,N},&R),XMQTT_SESSION_DONE,"other-platform image restore");memset(B,0,sizeof(B));miReplay(R,V,5);miStop(R,6);}
    puts("[PASS] actual cross-process/platform Session image and canonical replay");return 0;
}
int main(int Argc,char** Argv)
{if(Argc>1)return imageFile(Argc,Argv);for(unsigned V=0;V<2;++V){testImageRoundtrip(V?XMQTT_VERSION_311:XMQTT_VERSION_5,false);testImageRoundtrip(V?XMQTT_VERSION_311:XMQTT_VERSION_5,true);testImageNonpersistent(V?XMQTT_VERSION_311:XMQTT_VERSION_5);}testImageExpiry();testImagePropertiesAndPartial();testImageAssigned();puts("[PASS] Session images both versions/live/offline/QoS replay/receive identities/expiry/new epochs/old lifetimes");return 0;}
